// MALAYSIA_KEYWORDS removed - let DeepSeek determine relevance later
const BLOCKED_PATH_PARTS = ['/tag/','/tags/','/category/','/categories/','/archive','/archives','/search','/video/','/videos/','/gallery/','/galleries/','/photo/','/photos/','/topic/','/topics/','/live/'];
const PAYWALL_HINTS = ['subscribe','subscription','premium','paywall','login','sign-in','signin','register'];
const DIRECT_ALLOWED = ['thestar.com.my','nst.com.my','freemalaysiatoday.com','bernama.com','malaymail.com','thesundaily.my'];

function hostnameOf(value) {
  try { return new URL(value).hostname.toLowerCase().replace(/^www\./,''); } catch { return ''; }
}
function cleanText(value) {
  return String(value || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}
function blockedUrl(url) {
  const lower = String(url || '').toLowerCase();
  return BLOCKED_PATH_PARTS.some(p => lower.includes(p)) || PAYWALL_HINTS.some(p => lower.includes(p));
}
function articleish(url) {
  if (!url) return false;
  const lower = url.toLowerCase();
  if (blockedUrl(lower)) return false;
  return /\/20\d{2}\//.test(lower) || /\/202\d\/\d{2}\/\d{2}\//.test(lower) || /-[a-z0-9-]{8,}$/.test(lower) || /\/news\//.test(lower) || /\/business\//.test(lower) || /\/markets\//.test(lower) || /\/nation\//.test(lower);
}
function categoryFor(text, url, sourceMode) {
  const hay = `${text} ${url}`.toLowerCase();
  if (sourceMode === 'bursa_announcements') return ['business','bursa-announcements'];
  if (/bursa|stocks?|shares?|ipo|earnings|ringgit|market|bank negara|petronas|maybank|cimb|economy|economic/.test(hay)) return ['business', 'markets'];
  if (/cabinet|parliament|minister|government|election|umno|pkr|pas|dap|anwar|zahid/.test(hay)) return ['government','politics'];
  if (/police|court|crime|arrest|charged|murder|scam|raid/.test(hay)) return ['crime','general'];
  if (/flood|weather|rain|monsoon|landslide|haze|earthquake|fire/.test(hay)) return ['weather','alerts'];
  if (/football|badminton|hockey|motogp|formula 1|sport/.test(hay)) return ['sports','general'];
  if (/school|university|education|student|spm|stpm/.test(hay)) return ['education','general'];
  if (/hospital|health|ministry of health|covid|dengue|medical/.test(hay)) return ['health','general'];
  if (/ai|technology|tech|digital|telecom|5g|startup|cyber/.test(hay)) return ['technology','general'];
  return ['others','general'];
}

// Extract actual article URL from Google News RSS link format (no fetch needed)
function resolveGoogleNewsUrl(url) {
  if (!url || !url.includes('news.google.com')) return url;
  // Already a direct article URL
  if (url.includes('/articles/') && !url.includes('/rss/')) return url;
  // Convert RSS article link to direct article link
  const match = url.match(/news\.google\.com\/rss\/articles\/([^\?]+)/);
  if (match) {
    return 'https://news.google.com/articles/' + match[1];
  }
  return url;
}

const out = [];
for (const wrapped of items) {
  const item = wrapped.json || {};
  const title = cleanText(item.title || 'Untitled');
  const summary = cleanText(item.summary || item.contentSnippet || item.content || item.description || '');
  const sourceMode = item.source_mode || 'direct_seed';
  let finalUrl = item.link || item.url || '';

  // For Google Discovery, extract article URL directly (no fetch needed)
  if (sourceMode === 'google_discovery' && finalUrl) {
    finalUrl = resolveGoogleNewsUrl(finalUrl);
  }

  const finalDomain = hostnameOf(finalUrl);
  const text = title + ' ' + summary + ' ' + finalUrl;
  // Malaysia relevance check removed - let DeepSeek determine later
  // articleish check removed - let DeepSeek determine if it's an article later
  if (sourceMode === 'direct_seed' && !DIRECT_ALLOWED.some(d => finalDomain === d || finalDomain.endsWith('.' + d))) continue;
  if (sourceMode === 'google_discovery' && (!finalDomain || finalDomain === 'news.google.com' || blockedUrl(finalUrl))) continue;
  if (sourceMode === 'bursa_announcements' && !(finalDomain === 'bursamalaysia.com' || finalDomain.endsWith('.bursamalaysia.com'))) continue;

  const [primary_category, secondary_category] = categoryFor(text, finalUrl, sourceMode);
  out.push({ json: {
    title,
    url: finalUrl,
    source: item.source_label || item.source_name || finalDomain || 'unknown',
    source_label: item.source_label || item.source_name || finalDomain || 'unknown',
    source_name: item.source_name || item.source_label || finalDomain || 'unknown',
    source_domain: finalDomain || item.source_domain || '',
    published_at: item.isoDate || item.pubDate || item.datePublished || new Date().toISOString(),
    summary: summary.slice(0, 500),
    primary_category,
    secondary_category,
    source_mode: sourceMode
  }});
}

const seen = new Set();
return out.filter(entry => {
  const key = (entry.json.url || '').toLowerCase().replace(/#.*$/, '').replace(/\?.*$/, '');
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
});
